"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command "@'
'use strict';
const fs = require('node:fs');
const assert = require('node:assert/strict');
const read = path => {
  const [header, ...lines] = fs.readFileSync(path, 'utf8').trim().split(/\\r?\\n/);
  const fields = header.split(',');
  return lines.map(line => Object.fromEntries(line.split(',').map((value, i) => [fields[i], value])));
};
const pairs = read('evidence/pairs.csv');
const refs = new Map(read('evidence/reference.csv').map(r => [r.pair_id, r]));
const guides = new Map(read('evidence/guide.csv').map(r => [r.pair_id, r]));
const rows = pairs.map(p => {
  const r = refs.get(p.pair_id), g = guides.get(p.pair_id);
  assert(r && g);
  const rt = r.seconds === '' ? null : Number(r.seconds);
  const gt = g.seconds === '' ? null : Number(g.seconds);
  assert(rt === null || (Number.isFinite(rt) && rt > 0));
  assert(gt === null || (Number.isFinite(gt) && gt > 0));
  for (const item of [r, g]) for (const field of ['correct', 'assisted']) assert(['true','false'].includes(item[field]));
  return {...p, reference_seconds: rt, guide_seconds: gt, saved: rt "'!== null && gt !== null ? rt - gt : null, reference_correct: r.correct === '"'true', guide_correct: g.correct === 'true', reference_assisted: r.assisted === 'true', guide_assisted: g.assisted === 'true'};
});
const eligible = rows.filter(r => r.saved "'!== null);
const sum = (rs, field) => rs.reduce((total, r) => total + r[field], 0);
const metrics = {
  eligible_time_pairs: eligible.length,
  reference_seconds: sum(eligible, '"'reference_seconds'),
  guide_seconds: sum(eligible, 'guide_seconds'),
  time_saved_seconds: sum(eligible, 'saved'),
  faster_pairs: eligible.filter(r => r.saved > 0).length,
  slower_pairs: eligible.filter(r => r.saved < 0).length,
  tied_pairs: eligible.filter(r => r.saved === 0).length,
  accuracy_pairs: rows.length,
  reference_correct: rows.filter(r => r.reference_correct).length,
  guide_correct: rows.filter(r => r.guide_correct).length
};
const summarize = rs => ({pairs: rs.length, reference_seconds: sum(rs, 'reference_seconds'), guide_seconds: sum(rs, 'guide_seconds'), saved: sum(rs, 'saved'), saving_percent: 100 * sum(rs, 'saved') / sum(rs, 'reference_seconds')});
const order = Object.fromEntries(['reference','guide'].map(f => [f, summarize(eligible.filter(r => r.first_format === f))]));
const volunteers = Object.fromEntries([...new Set(rows.map(r => r.volunteer_id))].map(v => [v, summarize(eligible.filter(r => r.volunteer_id === v))]));
const orderBalance = Object.fromEntries(Object.keys(volunteers).map(v => [v, rows.filter(r => r.volunteer_id === v).map(r => r.first_format)]));
for (const formats of Object.values(orderBalance)) assert.deepEqual([...formats].sort(), ['guide','reference']);
process.stdout.write(JSON.stringify({metrics, percent_saved: 100 * metrics.time_saved_seconds / metrics.reference_seconds, rows, order, volunteers, orderBalance, both_unassisted: summarize(eligible.filter(r => "'!r.reference_assisted && !r.guide_assisted)), reference_assisted: rows.filter(r => r.reference_assisted).map(r => r.pair_id), guide_assisted: rows.filter(r => r.guide_assisted).map(r => r.pair_id)}, null, 2) + '"'\\n');
'@ | node"

"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$studyPairs = @(Import-Csv -LiteralPath evidence/pairs.csv)
$referenceById = @{}
$guideById = @{}
Import-Csv -LiteralPath evidence/reference.csv | ForEach-Object { $referenceById.Add($_.pair_id, $_) }
Import-Csv -LiteralPath evidence/guide.csv | ForEach-Object { $guideById.Add($_.pair_id, $_) }
$independentMetrics = [ordered]@{
  eligible_time_pairs = 0
  reference_seconds = 0
  guide_seconds = 0
  time_saved_seconds = 0
  faster_pairs = 0
  slower_pairs = 0
  tied_pairs = 0
  accuracy_pairs = $studyPairs.Count
  reference_correct = 0
  guide_correct = 0
}
foreach ($studyPair in $studyPairs) {
  $referenceRow = $referenceById[$studyPair.pair_id]
  $guideRow = $guideById[$studyPair.pair_id]
  if ($null -eq $referenceRow -or $null -eq $guideRow) { throw '"'Missing ID match' }
  if ("'$referenceRow.correct -eq '"'true') { "'$independentMetrics.reference_correct++ }
  if ($guideRow.correct -eq '"'true') { "'$independentMetrics.guide_correct++ }
  if (-not [string]::IsNullOrWhiteSpace($referenceRow.seconds) -and -not [string]::IsNullOrWhiteSpace($guideRow.seconds)) {
    $referenceTime = [int]$referenceRow.seconds
    $guideTime = [int]$guideRow.seconds
    if ($referenceTime -le 0 -or $guideTime -le 0) { throw '"'Nonpositive observed time' }
    "'$independentMetrics.eligible_time_pairs++
    $independentMetrics.reference_seconds += $referenceTime
    $independentMetrics.guide_seconds += $guideTime
    $pairSaving = $referenceTime - $guideTime
    $independentMetrics.time_saved_seconds += $pairSaving
    if ($pairSaving -gt 0) { $independentMetrics.faster_pairs++ }
    elseif ($pairSaving -lt 0) { $independentMetrics.slower_pairs++ }
    else { $independentMetrics.tied_pairs++ }
  }
}
$writtenMetrics = Get-Content -LiteralPath audit/metrics.json -Raw | ConvertFrom-Json
$fieldDifference = @(Compare-Object -ReferenceObject @($independentMetrics.Keys | Sort-Object) -DifferenceObject @($writtenMetrics.PSObject.Properties.Name | Sort-Object))
if ($fieldDifference.Count -ne 0) { throw '"'JSON fields do not match protocol' }
foreach ("'$field in $independentMetrics.Keys) {
  $writtenValue = $writtenMetrics.$field
  if ($writtenValue -isnot [long] -and $writtenValue -isnot [int] -and $writtenValue -isnot [double] -and $writtenValue -isnot [decimal]) { throw "Nonnumeric field: $field" }
  if ($writtenValue -ne $independentMetrics[$field]) { throw "Incorrect metric: $field" }
}
if ($writtenMetrics.faster_pairs + $writtenMetrics.slower_pairs + $writtenMetrics.tied_pairs -ne $writtenMetrics.eligible_time_pairs) { throw '"'Directional counts do not reconcile' }
if ("'$writtenMetrics.reference_seconds - $writtenMetrics.guide_seconds -ne $writtenMetrics.time_saved_seconds) { throw '"'Time totals do not reconcile' }
[PSCustomObject]@{
  result = 'PASS: independent PowerShell calculations and exact ten-field numeric JSON schema'
  metrics = "'$independentMetrics
  saving_percent = 100 * $independentMetrics.time_saved_seconds / $independentMetrics.reference_seconds
  reference_accuracy_percent = 100 * $independentMetrics.reference_correct / $independentMetrics.accuracy_pairs
  guide_accuracy_percent = 100 * $independentMetrics.guide_correct / $independentMetrics.accuracy_pairs
} | ConvertTo-Json -Depth 4'

"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$sourceFiles = @(rg --files --hidden -g '"'"'!.git/**'"' -g '"'!audit/**'"')
"'$sourceFiles | Sort-Object | ForEach-Object {
  $sourceHash = Get-FileHash -LiteralPath $_ -Algorithm SHA256
  [PSCustomObject]@{ path = $_.Replace('"'\\','/'); sha256 = "'$sourceHash.Hash }
} | ConvertTo-Json
